@import url('https://fonts.googleapis.com/css2?family=Archivo+Black&family=Archivo:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Brutalism — thick black borders, hard offset shadows, saturated primaries */
.theme-brutalism {
  --bg: oklch(0.94 0.15 100);
  --surface: oklch(1 0 0);
  --surface-2: oklch(0.87 0.19 96);
  --fg: oklch(0.12 0 0);
  --fg-muted: oklch(0.35 0 0);
  --accent: oklch(0.68 0.24 350);
  --accent-fg: oklch(1 0 0);
  --accent-2: oklch(0.58 0.24 258);
  --line: oklch(0.12 0 0);
  --success: oklch(0.68 0.2 145);
  --warning: oklch(0.8 0.19 85);
  --danger: oklch(0.6 0.25 27);

  --radius: 0px;
  --radius-sm: 0px;
  --radius-lg: 0px;
  --radius-pill: 0px;

  --shadow-1: 4px 4px 0 0 var(--line);
  --shadow-2: 7px 7px 0 0 var(--line);
  --shadow-3: 11px 11px 0 0 var(--line);
  --glow: 7px 7px 0 0 var(--accent);

  --border-width: 3px;
  --blur-amount: 0px;

  --font-display: "Archivo Black", "Arial Black", sans-serif;
  --font-body: "Archivo", "Helvetica Neue", Arial, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.01em;
  --label-transform: uppercase;
  --label-tracking: 0.06em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-brutalism h1,
.theme-brutalism h2,
.theme-brutalism h3 {
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-brutalism h1, .theme-brutalism h2 { text-transform: uppercase; text-shadow: 4px 4px 0 var(--accent-2, var(--accent)); }
.theme-brutalism button { text-transform: uppercase; }
.theme-brutalism button:hover { transform: translate(-2px, -2px); box-shadow: 6px 6px 0 var(--line); }
.theme-brutalism button:active { transform: translate(2px, 2px); box-shadow: none; }

/* depth */
.theme-brutalism thead th { background: var(--fg); color: var(--bg); text-transform: uppercase; letter-spacing: 0.08em; border: var(--border-width) solid var(--line); }
.theme-brutalism td { border-bottom: 2px solid var(--line); }
.theme-brutalism tbody tr:hover td { background: var(--surface-2); }
.theme-brutalism input, .theme-brutalism textarea, .theme-brutalism select { border: var(--border-width) solid var(--line); background: var(--surface); box-shadow: none; }
.theme-brutalism input:focus-visible, .theme-brutalism textarea:focus-visible, .theme-brutalism select:focus-visible { outline: none; box-shadow: 4px 4px 0 0 var(--accent); transform: translate(-2px, -2px); }
.theme-brutalism kbd { font-family: var(--font-mono); border: 2px solid var(--line); background: var(--surface); box-shadow: 2px 2px 0 var(--line); padding: 0.1em 0.4em; text-transform: uppercase; }
.theme-brutalism a { color: var(--fg); font-weight: 700; text-decoration: underline; text-decoration-thickness: 3px; text-underline-offset: 3px; }
.theme-brutalism a:hover { background: var(--fg); color: var(--bg); text-decoration: none; }
.theme-brutalism ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-brutalism ::-webkit-scrollbar { width: 14px; height: 14px; }
.theme-brutalism ::-webkit-scrollbar-track { background: var(--bg); border-left: 3px solid var(--line); }
.theme-brutalism ::-webkit-scrollbar-thumb { background: var(--fg); border: 3px solid var(--bg); border-radius: 0; }
.theme-brutalism .label-caps { font-weight: 900; border-bottom: 3px solid var(--accent); display: inline-block; }
.theme-brutalism .themed-border { border-left: 8px solid var(--accent); }
.theme-brutalism hr { border: none; border-top: 4px solid var(--line); }

/* alt mode: blackout brutalism — same violence, lights off */
.theme-brutalism.alt-mode {
  --bg: oklch(0.16 0.01 100);
  --surface: oklch(0.12 0 0);
  --surface-2: oklch(0.24 0.05 100);
  --fg: oklch(0.96 0.02 100);
  --fg-muted: oklch(0.75 0.02 100);
  --line: oklch(0.96 0.02 100);
  --accent: oklch(0.692 0.220 350.0);
  --accent-2: oklch(0.7 0.18 258);
  --shadow-1: 4px 4px 0 0 var(--line);
  --shadow-2: 7px 7px 0 0 var(--line);
  --shadow-3: 11px 11px 0 0 var(--line);
  --glow: 7px 7px 0 0 var(--accent);
}
.theme-brutalism.alt-mode thead th { background: var(--fg); color: var(--surface); }
.theme-brutalism.alt-mode a:hover { background: var(--fg); color: var(--surface); }
.theme-brutalism.alt-mode ::-webkit-scrollbar-thumb { background: var(--fg); border-color: var(--bg); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }
